package com.example.expo.Model;import com.example.expo.Enum.VisitStatus;import com.example.expo.Model.Destination;import jakarta.persistence.*;import lombok.AllArgsConstructor;import lombok.Data;import lombok.NoArgsConstructor;import java.time.LocalDateTime;@Entity@Data@AllArgsConstructor@NoArgsConstructor@Table(        uniqueConstraints = {                @UniqueConstraint(                        columnNames = {"user_id", "destination_id"}                )        })public class UserDestinationProgress {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Column(name = "user_id", nullable = false)    private Long userId;    @ManyToOne(optional = false)    @JoinColumn(name = "destination_id", nullable = false)    private Destination destination;    @Enumerated(EnumType.STRING)    @Column(nullable = false)    private VisitStatus status;    private LocalDateTime visitedAt;    private LocalDateTime createdAt;    private LocalDateTime updatedAt;    @PrePersist    public void onCreate() {        createdAt = LocalDateTime.now();        updatedAt = LocalDateTime.now();    }    @PreUpdate    public void onUpdate() {        updatedAt = LocalDateTime.now();    }}